// GENERATED by engine/scripts/recheck.mts — do not edit by hand.
// Merge-on-write: each recheck run adds or replaces its own addresses.
//
//   pnpm --filter @sidik/engine recheck COBIE KEYCAT NVO CASHCAT
//
// The honeypot probe, re-executed against a fork of Base at the head block of
// the day it ran, for addresses whose recorded verdict a read-only scanner
// disputes. The recorded verdict describes block 50,200,000; a scanner reading
// describes the day it was asked; this is the only thing that tells "the
// token changed since the pin" from "the scanner is wrong".
//
// Context, never evidence: nothing here changes a recorded verdict.

export interface Recheck {
  /** The head block the fork was taken at (head − 20, so it cannot reorg away). */
  headBlock: string;
  /** ISO date the recheck ran. */
  checkedOn: string;
  /** Honeypot probe status at that head. */
  status: "PASS" | "FAIL" | "NA";
  /** The probe's one-line verdict at that head. */
  title: string;
}

