/** The head-of-day recheck for an address, if one was run. */
export function recheckOf(address: string): Recheck | undefined {
  const key = String(address).toLowerCase();
  // hasOwn, not a bare lookup: "constructor" is a key on every object, and
  // the run page hands this result to a client component — a function there
  // is a render error, not a 404.
  return Object.hasOwn(RECHECKS, key) ? RECHECKS[key] : undefined;
}
